    reset_user_password,
    resolve_session,
    revoke_session,
    set_user_active,
    update_user,
)

SESSION_COOKIE_NAME = "nfx_session"
INVALID_CREDENTIALS = {"detail": "Credenciais inválidas."}


def _json_body(request: HttpRequest) -> dict[str, object] | None:
    try:
        body = json.loads(request.body)
    except (TypeError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    return body if isinstance(body, dict) else None


def _request_ip(request: HttpRequest) -> str:
    return str(request.META.get("REMOTE_ADDR", ""))


def _user_payload(user: object) -> dict[str, object]:
    from nfx.identity.models import User

    assert isinstance(user, User)
    return {
        "id": str(user.id),
        "name": user.name,
        "email": user.email,
        "role": user.role,
        "active": user.active,
        "version": user.version,
    }


def _integer(body: dict[str, object], name: str) -> int | None:
    value = body.get(name)
    return value if isinstance(value, int) and value > 0 else None


def _admin_error(exc: Exception) -> JsonResponse:
    if isinstance(exc, DuplicateUserEmail):
        return JsonResponse({"detail": "E-mail já cadastrado."}, status=409)
    if isinstance(exc, UserVersionConflict):
        return JsonResponse({"detail": "Usuário alterado por outra solicitação."}, status=409)
    if isinstance(exc, LastAdministrator):
        return JsonResponse({"detail": "É necessário manter um Administrador ativo."}, status=409)
    return JsonResponse({"detail": "Não foi possível concluir a operação."}, status=400)


@require_GET
@ensure_csrf_cookie
def csrf(_: HttpRequest) -> JsonResponse:
    return JsonResponse({"detail": "CSRF pronto."})


@require_POST
def login(request: HttpRequest) -> JsonResponse:
    body = _json_body(request)
    email = body.get("email") if body else None
    password = body.get("password") if body else None
    if not isinstance(email, str) or not isinstance(password, str):
        return JsonResponse(INVALID_CREDENTIALS, status=401)
    token, identity = authenticate(
        email, password, _request_ip(request), request.headers.get("User-Agent", "")
    )
    if token is None or identity is None:
        return JsonResponse(INVALID_CREDENTIALS, status=401)
    response = JsonResponse(
        {"user": {"id": identity.user_id, "name": identity.name, "role": identity.role}}
    )
    response.set_cookie(
        SESSION_COOKIE_NAME, token, secure=True, httponly=True, samesite="Lax", path="/api/"
    )
    response["Cache-Control"] = "no-store"
    return response


@require_POST
def logout(request: HttpRequest) -> JsonResponse:
    revoke_session(request.COOKIES.get(SESSION_COOKIE_NAME))
    response = JsonResponse({"detail": "Sessão encerrada."})
    response.delete_cookie(SESSION_COOKIE_NAME, path="/api/", samesite="Lax")
    response["Cache-Control"] = "no-store"
    return response


@require_GET
def session(request: HttpRequest) -> JsonResponse:
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME))
    if identity is None:
        return JsonResponse({"detail": "Não autenticado."}, status=401)
    response = JsonResponse(
        {"user": {"id": identity.user_id, "name": identity.name, "role": identity.role}}
    )
    response["Cache-Control"] = "no-store"
    return response


def protected(
    action: Action, *, owner_id: Callable[[HttpRequest], str | None] | None = None
) -> Callable[[Callable[..., HttpResponse]], Callable[..., HttpResponse]]:
    def decorator(view: Callable[..., HttpResponse]) -> Callable[..., HttpResponse]:
        def wrapped(request: HttpRequest, *args: object, **kwargs: object) -> HttpResponse:
            identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME))
            if not require_authorized(
                identity, action.value, owner_id(request) if owner_id else None
            ):
                return JsonResponse({"detail": "Acesso negado."}, status=403)
            return view(request, *args, **kwargs)

        return wrapped

    return decorator


@require_GET
@protected(Action.ADMINISTER_USERS)
def users(request: HttpRequest) -> JsonResponse:
    from nfx.identity.models import Role, User

    active = request.GET.get("active")
    role = request.GET.get("role")
    try:
        limit = min(max(int(request.GET.get("limit", "50")), 1), 100)
        cursor = request.GET.get("cursor", "")
    except ValueError:
        return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
    queryset = User.objects.order_by("id")
    if active not in {None, "true", "false"}:
        return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
    if active in {"true", "false"}:
        queryset = queryset.filter(active=active == "true")
    if role:
        if role not in Role.values:
            return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
        queryset = queryset.filter(role=role)
    if cursor:
        try:
            cursor_id = UUID(cursor)
        except ValueError:
            return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
        queryset = queryset.filter(id__gt=cursor_id)
    rows = list(queryset[: limit + 1])
    return JsonResponse(
        {
            "users": [_user_payload(row) for row in rows[:limit]],
            "next_cursor": str(rows[limit].id) if len(rows) > limit else None,
        }
    )


@require_POST
@protected(Action.ADMINISTER_USERS)
def user_create(request: HttpRequest) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    if body is None or identity is None:
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    required = ("name", "email", "role", "password")
    if any(not isinstance(body.get(field), str) for field in required):
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        user = create_user(
            actor=identity,
            name=str(body["name"]),
            email=str(body["email"]),
            role=str(body["role"]),
            password=str(body["password"]),
            ip_address=_request_ip(request),
        )
    except UserAdministrationError as exc:
        return _admin_error(exc)
    return JsonResponse({"user": _user_payload(user)}, status=201)


@require_http_methods(["PATCH"])
@protected(Action.ADMINISTER_USERS)
def user_update(request: HttpRequest, user_id: str) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    version = _integer(body or {}, "version")
    if (
        body is None
        or identity is None
        or version is None
        or not isinstance(body.get("name"), str)
        or not isinstance(body.get("email"), str)
    ):
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        user = update_user(
            actor=identity,
            user_id=user_id,
            version=version,
            name=str(body["name"]),
            email=str(body["email"]),
            ip_address=_request_ip(request),
        )
    except (UserAdministrationError, ValueError) as exc:
        return _admin_error(exc)
    return JsonResponse({"user": _user_payload(user)})


def _admin_action(request: HttpRequest, user_id: str, operation: str) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    version = _integer(body or {}, "version")
    reason = body.get("reason") if body else None
    reason_value = reason if isinstance(reason, str) else ""
    if body is None or identity is None or version is None:
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        if operation == "role":
            role = body.get("role")
            if not isinstance(role, str):
                raise UserAdministrationError("Invalid role")
            user = change_user_role(
                actor=identity,
                user_id=user_id,
                version=version,
                role=role,
                reason=reason_value,
                ip_address=_request_ip(request),
            )
        elif operation == "password":
            password = body.get("password")
            if not isinstance(password, str):
                raise UserAdministrationError("Invalid password")
            user = reset_user_password(
                actor=identity,
                user_id=user_id,
                version=version,
                password=password,
                reason=reason_value,
                ip_address=_request_ip(request),
            )
"""Transactional contracts for durable jobs, leases, and safe handlers."""

from __future__ import annotations

import logging
import random
import re
import time
from collections.abc import Callable, Mapping
from datetime import datetime, timedelta
from typing import Any
from uuid import UUID, uuid4

from django.db import IntegrityError, OperationalError, transaction
from django.utils import timezone

from nfx.jobs.handlers import HandlerOutcome, get_handler
from nfx.jobs.models import Job, JobOutcomeKind, JobPolicy, JobState
from nfx.jobs.policy import select_policy

logger = logging.getLogger(__name__)

_SAFE_KEY = re.compile(r"^[a-zA-Z][a-zA-Z0-9_.-]{0,127}$")
_FORBIDDEN = re.compile(
    r"(?:pfx|pem|xml|pdf|token|credential|password|secret|private|content|binary|blob)", re.I
)
_SAFE_ERROR = re.compile(r"^[a-z][a-z0-9_.-]{0,63}$")


class JobEngineError(RuntimeError):
    """Base error for rejected job operations."""


class InvalidJobPayload(JobEngineError, ValueError):
    """Payload or result contains data outside the referential safe contract."""


class InvalidTransition(JobEngineError):
    """The job is not in a state that supports the requested operation."""


class LeaseLost(JobEngineError):
    """The caller no longer owns a valid lease."""


def _validate_safe_value(value: Any, *, path: str = "payload") -> Any:
    if isinstance(value, Mapping):
        result: dict[str, Any] = {}
        for key, item in value.items():
            name = str(key)
            if not _SAFE_KEY.fullmatch(name) or _FORBIDDEN.search(name):
                raise InvalidJobPayload(f"unsafe field at {path}")
            result[name] = _validate_safe_value(item, path=f"{path}.{name}")
        return result
    if isinstance(value, list):
        return [_validate_safe_value(item, path=f"{path}[]") for item in value]
    if value is None or isinstance(value, bool | int | float | str):
        if isinstance(value, str) and (value.lstrip().startswith("<") or value.startswith("%PDF")):
            raise InvalidJobPayload(f"unsafe value at {path}")
        return value
    raise InvalidJobPayload(f"unsupported value at {path}")


def _safe_error_code(value: str) -> str:
    return value if _SAFE_ERROR.fullmatch(value) else "handler_failed"


class JobEngine:
    """Owns all durable state transitions for background jobs."""

    def __init__(
        self,
        *,
        clock: Callable[[], datetime] = timezone.now,
        lease_duration: timedelta = timedelta(seconds=30),
        jitter_source: Callable[[int], int] | None = None,
    ) -> None:
        if lease_duration <= timedelta(0):
            raise ValueError("lease_duration must be positive")
        self.clock = clock
        self.lease_duration = lease_duration
        self.jitter_source = jitter_source or self._random_jitter

    @staticmethod
    def _random_jitter(max_seconds: int) -> int:
        return random.SystemRandom().randint(-max_seconds, max_seconds) if max_seconds else 0

    def enqueue(
        self,
        *,
        job_type: str,
        logical_target: str,
        payload: Mapping[str, Any],
        idempotency_key: str,
        priority: int = 0,
        scheduled_at: datetime | None = None,
        policy: JobPolicy | None = None,
        policy_source: str | None = None,
        policy_flow: str | None = None,
    ) -> Job:
        safe_payload = _validate_safe_value(payload)
        due_at = scheduled_at or self.clock()
        if timezone.is_naive(due_at):
            raise ValueError("scheduled_at must be timezone-aware")
        if not job_type or not logical_target or not idempotency_key:
            raise ValueError("job_type, logical_target, and idempotency_key are required")
        if policy is not None and (policy_source is not None or policy_flow is not None):
            raise ValueError("use policy or policy scope, not both")
        if (policy_source is None) != (policy_flow is None):
            raise ValueError("policy_source and policy_flow must be provided together")
        if policy_source is not None and policy_flow is not None:
            policy = select_policy(source=policy_source, flow=policy_flow, at=due_at)
        if policy is not None and not (
            policy.valid_from <= due_at
            and (policy.valid_until is None or due_at < policy.valid_until)
        ):
            raise ValueError("policy is not valid at the scheduled time")

        for _ in range(2):
            try:
                with transaction.atomic():
                    existing = (
                        Job.objects.select_for_update()
                        .filter(
                            idempotency_key=idempotency_key,
                            state__in=(JobState.QUEUED, JobState.RUNNING),
                        )
                        .first()
                    )
                    if existing is not None:
                        return existing
                    return Job.objects.create(
                        job_type=job_type,
                        logical_target=logical_target,
                        payload=safe_payload,
                        priority=priority,
                        idempotency_key=idempotency_key,
                        scheduled_at=due_at,
                        effective_policy=policy,
                    )
            except IntegrityError:
                # A concurrent insert won the partial unique constraint. The
                # next iteration observes it under a row lock.
                continue
        raise JobEngineError("could not resolve active idempotency key")

    def reclaim_expired(self) -> int:
        now = self.clock()
        with transaction.atomic():
            return Job.objects.filter(
                state=JobState.RUNNING,
                lease_expires_at__lte=now,
            ).update(
                state=JobState.QUEUED,
                scheduled_at=now,
                lease_owner=None,
                lease_issued_at=None,
                lease_expires_at=None,
                safe_error="lease_expired",
                updated_at=now,
            )

    def recover(self) -> tuple[int, int]:
        """Reclaim leases and report queued work due for a worker."""
        now = self.clock()
        with transaction.atomic():
            reclaimed = Job.objects.filter(
                state=JobState.RUNNING,
                lease_expires_at__lte=now,
            ).update(
                state=JobState.QUEUED,
                scheduled_at=now,
                lease_owner=None,
                lease_issued_at=None,
                lease_expires_at=None,
                safe_error="lease_expired",
                updated_at=now,
            )
            due = Job.objects.filter(state=JobState.QUEUED, scheduled_at__lte=now).count()
        return reclaimed, due

    def claim(self, owner: str) -> Job | None:
        if not owner or not owner.strip():
            raise ValueError("owner is required")
        now = self.clock()
        with transaction.atomic():
            Job.objects.filter(
                state=JobState.RUNNING,
                lease_expires_at__lte=now,
            ).update(
                state=JobState.QUEUED,
                scheduled_at=now,
                lease_owner=None,
                lease_issued_at=None,
                lease_expires_at=None,
                safe_error="lease_expired",
                updated_at=now,
            )
            job = (
                Job.objects.select_for_update(skip_locked=True)
                .filter(state=JobState.QUEUED, scheduled_at__lte=now)
                .order_by("-priority", "scheduled_at", "created_at")
                .first()
            )
            if job is None:
                return None
            job.state = JobState.RUNNING
            job.lease_owner = owner
            job.lease_issued_at = now
            job.lease_expires_at = now + self.lease_duration
            job.last_attempt_at = now
            job.attempt_count += 1
            job.updated_at = now
            job.save(
                update_fields=[
                    "state",
                    "lease_owner",
                    "lease_issued_at",
                    "lease_expires_at",
                    "last_attempt_at",
                    "attempt_count",
                    "updated_at",
                ]
            )
            return job

    def _lease_update(self, job_id: UUID | str, owner: str, **fields: Any) -> Job:
        now = self.clock()
        with transaction.atomic():
            updated = Job.objects.filter(
                id=job_id,
                state=JobState.RUNNING,
                lease_owner=owner,
                lease_expires_at__gt=now,
            ).update(**fields, updated_at=now)
            if not updated:
                if Job.objects.filter(id=job_id, state=JobState.RUNNING).exists():
                    raise LeaseLost("job lease is no longer valid")
                raise InvalidTransition("job is not running")
            return Job.objects.get(id=job_id)
import { FormEvent, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";

type User = { id: string; name: string; role: "administrador" | "operador" | "visualizador" };
type AuditEvent = { id: string; sequence: number; occurred_at: string; action: string; entity_type: string; entity_id: string; result: string; reason: string; actor_id: string | null };
type ManagedUser = User & { email: string; active: boolean; version: number };
type CompanyFlow = { id: string; state: "habilitado" | "pausado" };
type Company = { id: string; cnpj: string; legal_name: string; status: "cadastrada" | "ativa" | "desativada"; first_collection_at: string | null; deactivation_reason: string | null; version: number; flows: Record<string, CompanyFlow>; enrichment: { status: string; public_non_authoritative: boolean; payload: unknown; error_code: string } | null };
type Certificate = { id: string; state: string; status: string; fingerprint_sha256: string; certificate_cnpj: string; not_before: string; not_after: string; days_until_expiry: number | null; key_version: number };

function cookie(name: string): string {
  return document.cookie.split("; ").find((part) => part.startsWith(`${name}=`))?.split("=")[1] ?? "";
}

function statusLabel(status: Company["status"]): string {
  return { cadastrada: "Cadastrada", ativa: "Ativa", desativada: "Desativada" }[status];
}

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const [auditEvents, setAuditEvents] = useState<AuditEvent[]>([]);
  const [managedUsers, setManagedUsers] = useState<ManagedUser[]>([]);
  const [newUser, setNewUser] = useState({ name: "", email: "", role: "visualizador", password: "" });
  const [companies, setCompanies] = useState<Company[]>([]);
  const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);
